import { screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { renderWithProviders } from "../../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../../types";
import { MemoryWriteEvent } from "./MemoryWriteEvent";

function memoryEvent(overrides: Partial<ConversationEvent>): ConversationEvent {
  return {
    id: "e1",
    conversationEventType: ConversationEventType.MemorySet,
    name: "card_replace.replacement_reason",
    value: "stolen",
    actionText: "",
    flowId: "",
    stepId: "",
    timestamp: "2020-01-01T00:00:00.000Z",
    originalTimestamp: 0,
    metadata: { parseData: {} },
    __typename: "ConversationEvent",
    ...overrides,
  };
}

describe("MemoryWriteEvent", () => {
  it("shows the bare entry name and value", () => {
    renderWithProviders(<MemoryWriteEvent event={memoryEvent({})} isSelected={false} />);
    expect(screen.queryByText(/^Slot/)).toBeNull();
    expect(screen.getByText("replacement_reason")).toBeInTheDocument();
    expect(screen.getByText(/set to/)).toBeInTheDocument();
    expect(screen.getByText("stolen")).toBeInTheDocument();
  });

  it("truncates long values to a one-line preview", () => {
    const longValue = [{ id: "1001", label: "River Cash (...3472)", eligible: true }];
    const { container } = renderWithProviders(
      <MemoryWriteEvent
        event={memoryEvent({ name: "card_list", value: longValue })}
        isSelected={false}
      />,
    );
    expect(container.textContent).toContain("…");
    expect((container.textContent ?? "").length).toBeLessThan(120);
  });

  it("renders scratchpad writes as the newly discovered fact", () => {
    const facts = [
      { key: "older_fact", value: "x" },
      { key: "lost_card_reported", value: "true", description: "User reported a lost card." },
    ];
    const { container } = renderWithProviders(
      <MemoryWriteEvent
        event={memoryEvent({ name: "system.__discovered__", value: facts })}
        isSelected={false}
      />,
    );
    expect(container.textContent).toContain("lost_card_reported discovered · true");
    expect(container.textContent).not.toContain("__discovered__");
    // Two facts total: the newest is shown, the one older fact is counted.
    expect(container.textContent).toContain("(+1 more)");
  });

  it("indicates the extra count when the scratchpad holds several facts", () => {
    const facts = [
      { key: "a", value: "1" },
      { key: "b", value: "2" },
      { key: "newest", value: "3" },
    ];
    const { container } = renderWithProviders(
      <MemoryWriteEvent
        event={memoryEvent({ name: "system.__discovered__", value: facts })}
        isSelected={false}
      />,
    );
    expect(container.textContent).toContain("newest discovered · 3");
    expect(container.textContent).toContain("(+2 more)");
  });

  it("shows a single discovered fact without an extra count", () => {
    const { container } = renderWithProviders(
      <MemoryWriteEvent
        event={memoryEvent({
          name: "system.__discovered__",
          value: [{ key: "only", value: "v" }],
        })}
        isSelected={false}
      />,
    );
    expect(container.textContent).toContain("only discovered · v");
    expect(container.textContent).not.toContain("more)");
  });

  it("hides engine housekeeping writes", () => {
    const { container } = renderWithProviders(
      <MemoryWriteEvent
        event={memoryEvent({ name: "consecutive_silence_timeouts", value: "0" })}
        isSelected={false}
      />,
    );
    expect(container.textContent).toBe("");
  });

  it("shows cleared entries without a value", () => {
    renderWithProviders(
      <MemoryWriteEvent
        event={memoryEvent({
          conversationEventType: ConversationEventType.MemoryCleared,
          value: null,
        })}
        isSelected={false}
      />,
    );
    expect(screen.getByText(/cleared/)).toBeInTheDocument();
  });

  it("renders a skill-scoped entry whose bare name matches a system slot", () => {
    renderWithProviders(
      <MemoryWriteEvent
        event={memoryEvent({ name: "card_replace.language", value: "en" })}
        isSelected={false}
      />,
    );
    expect(screen.getByText("language")).toBeInTheDocument();
    expect(screen.getByText(/set to/)).toBeInTheDocument();
    expect(screen.getByText("en")).toBeInTheDocument();

    const { container: systemContainer } = renderWithProviders(
      <MemoryWriteEvent
        event={memoryEvent({ name: "system.language", value: "en" })}
        isSelected={false}
      />,
    );
    expect(systemContainer.textContent).toBe("");
  });

  it("treats an undefined value as cleared", () => {
    renderWithProviders(
      <MemoryWriteEvent event={memoryEvent({ value: undefined })} isSelected={false} />,
    );
    expect(screen.getByText(/cleared/)).toBeInTheDocument();
    expect(screen.queryByText(/set to/)).toBeNull();
  });
});
